contracts/core/ProfileRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title ProfileRegistry
 * @dev Gestiona los perfiles de profesionales y empresas en la red Musubi
 */
contract ProfileRegistry is AccessControl, Pausable {
    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    // Estructuras
    struct Profile {
        address wallet;
        bool isActive;
        bool isCompany;
        uint256 karma;
        string metadataURI;
        uint256 createdAt;
        uint256 updatedAt;
    }

    // Mappings
    mapping(address => Profile) public profiles;
    mapping(address => bool) public verifiedProfiles;

    // Eventos
    event ProfileRegistered(address indexed wallet, bool isCompany);
    event ProfileUpdated(address indexed wallet);
    event ProfileVerified(address indexed wallet, address indexed verifier);

    /**
     * @dev Constructor
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
    }

    /**
     * @dev Registra un nuevo perfil profesional o empresarial
     * @param isCompany Indica si el perfil es de una empresa
     * @param metadataURI URI de los metadatos del perfil (IPFS)
     */
    function registerProfile(bool isCompany, string calldata metadataURI) external {
        require(profiles[msg.sender].wallet == address(0), "Profile already exists");

        profiles[msg.sender] = Profile({
            wallet: msg.sender,
            isActive: true,
            isCompany: isCompany,
            karma: 0,
            metadataURI: metadataURI,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        emit ProfileRegistered(msg.sender, isCompany);
    }

    /**
     * @dev Actualiza los metadatos de un perfil existente
     * @param metadataURI Nueva URI de los metadatos del perfil
     */
    function updateProfile(string calldata metadataURI) external {
        require(profiles[msg.sender].wallet != address(0), "Profile does not exist");

        profiles[msg.sender].metadataURI = metadataURI;
        profiles[msg.sender].updatedAt = block.timestamp;

        emit ProfileUpdated(msg.sender);
    }

    /**
     * @dev Verifica un perfil (solo verificadores autorizados)
     * @param wallet Dirección del perfil a verificar
     */
    function verifyProfile(address wallet) external onlyRole(VERIFIER_ROLE) {
        require(profiles[wallet].wallet != address(0), "Profile does not exist");
        require(!verifiedProfiles[wallet], "Profile already verified");

        verifiedProfiles[wallet] = true;

        emit ProfileVerified(wallet, msg.sender);
    }

    /**
     * @dev Actualiza el karma de un perfil (solo contratos autorizados)
     * @param wallet Dirección del perfil
     * @param karma Nuevo valor de karma
     */
    function updateKarma(address wallet, uint256 karma) external onlyRole(ADMIN_ROLE) {
        require(profiles[wallet].wallet != address(0), "Profile does not exist");

        profiles[wallet].karma = karma;
        profiles[wallet].updatedAt = block.timestamp;
    }

    /**
     * @dev Desactiva un perfil (solo admin)
     * @param wallet Dirección del perfil a desactivar
     */
    function deactivateProfile(address wallet) external onlyRole(ADMIN_ROLE) {
        require(profiles[wallet].wallet != address(0), "Profile does not exist");

        profiles[wallet].isActive = false;
        profiles[wallet].updatedAt = block.timestamp;
    }

    /**
     * @dev Pausa el contrato (solo admin)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Reanuda el contrato (solo admin)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/core/SkillSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title SkillSystem
 * @dev Implementa el sistema de declaración y validación de habilidades profesionales
 */
contract SkillSystem is AccessControl, Pausable {
    using Counters for Counters.Counter;

    // Contadores
    Counters.Counter private _skillIdCounter;
    Counters.Counter private _validationIdCounter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant KARMA_ROLE = keccak256("KARMA_ROLE");

    // Enums
    enum SkillLevel { Beginner, Intermediate, Advanced, Expert }
    enum ValidationStatus { Pending, Accepted, Disputed, Rejected }

    // Estructuras
    struct Skill {
        uint256 id;
        string name;
        string category;
        bool isActive;
    }

    struct DeclaredSkill {
        uint256 id;
        uint256 skillId;
        address professional;
        SkillLevel declaredLevel;
        uint256 karma;
        uint256 declaredAt;
    }

    struct Validation {
        uint256 id;
        uint256 declaredSkillId;
        address validator;
        SkillLevel validatedLevel;
        string context;
        ValidationStatus status;
        uint256 createdAt;
        uint256 respondedAt;
    }

    // Mappings
    mapping(uint256 => Skill) public skills;
    mapping(uint256 => DeclaredSkill) public declaredSkills;
    mapping(address => uint256[]) public professionalSkills;
    mapping(uint256 => Validation[]) public skillValidations;
    mapping(uint256 => uint256) public skillKarma;

    // Eventos
    event SkillCreated(uint256 indexed skillId, string name, string category);
    event SkillDeclared(uint256 indexed declaredSkillId, address indexed professional, uint256 skillId, SkillLevel level);
    event ValidationRequested(uint256 indexed validationId, uint256 indexed declaredSkillId, address indexed validator);
    event ValidationResponded(uint256 indexed validationId, ValidationStatus status);
    event KarmaUpdated(address indexed professional, uint256 indexed skillId, uint256 karma);

    /**
     * @dev Constructor
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(KARMA_ROLE, msg.sender);
    }

    /**
     * @dev Crea una nueva habilidad en el sistema
     * @param name Nombre de la habilidad
     * @param category Categoría de la habilidad
     */
    function createSkill(string calldata name, string calldata category) external onlyRole(ADMIN_ROLE) {
        uint256 skillId = _skillIdCounter.current();
        _skillIdCounter.increment();

        skills[skillId] = Skill({
            id: skillId,
            name: name,
            category: category,
            isActive: true
        });

        emit SkillCreated(skillId, name, category);
    }

    /**
     * @dev Declara una habilidad para un profesional
     * @param skillId ID de la habilidad
     * @param level Nivel declarado
     */
    function declareSkill(uint256 skillId, SkillLevel level) external whenNotPaused {
        require(skills[skillId].isActive, "Skill not active");

        uint256 declaredSkillId = _validationIdCounter.current();
        _validationIdCounter.increment();

        declaredSkills[declaredSkillId] = DeclaredSkill({
            id: declaredSkillId,
            skillId: skillId,
            professional: msg.sender,
            declaredLevel: level,
            karma: 0,
            declaredAt: block.timestamp
        });

        professionalSkills[msg.sender].push(declaredSkillId);

        emit SkillDeclared(declaredSkillId, msg.sender, skillId, level);
    }

    /**
     * @dev Solicita validación de una habilidad a un validador
     * @param declaredSkillId ID de la habilidad declarada
     * @param validator Dirección del validador
     * @param context Contexto de la validación
     */
    function requestValidation(uint256 declaredSkillId, address validator, string calldata context) external whenNotPaused {
        require(declaredSkills[declaredSkillId].professional == msg.sender, "Not skill owner");

        uint256 validationId = skillValidations[declaredSkillId].length;

        skillValidations[declaredSkillId].push(Validation({
            id: validationId,
            declaredSkillId: declaredSkillId,
            validator: validator,
            validatedLevel: SkillLevel.Beginner,
            context: context,
            status: ValidationStatus.Pending,
            createdAt: block.timestamp,
            respondedAt: 0
        }));

        emit ValidationRequested(validationId, declaredSkillId, validator);
    }

    /**
     * @dev Valida una habilidad (responde a una solicitud de validación)
     * @param declaredSkillId ID de la habilidad declarada
     * @param validationId ID de la validación
     * @param level Nivel validado
     */
    function validateSkill(uint256 declaredSkillId, uint256 validationId, SkillLevel level) external whenNotPaused {
        Validation storage validation = skillValidations[declaredSkillId][validationId];

        require(validation.validator == msg.sender, "Not validator");
        require(validation.status == ValidationStatus.Pending, "Not pending");

        validation.validatedLevel = level;
        validation.status = ValidationStatus.Accepted;
        validation.respondedAt = block.timestamp;

        // Actualizar karma
        _updateKarma(declaredSkillId);

        emit ValidationResponded(validationId, ValidationStatus.Accepted);
    }

    /**
     * @dev Disputa una validación
     * @param declaredSkillId ID de la habilidad declarada
     * @param validationId ID de la validación
     */
    function disputeValidation(uint256 declaredSkillId, uint256 validationId) external whenNotPaused {
        Validation storage validation = skillValidations[declaredSkillId][validationId];
        DeclaredSkill storage declaredSkill = declaredSkills[declaredSkillId];

        require(declaredSkill.professional == msg.sender || validation.validator == msg.sender, "Not authorized");
        require(validation.status == ValidationStatus.Pending || validation.status == ValidationStatus.Accepted, "Cannot dispute");

        validation.status = ValidationStatus.Disputed;
        validation.respondedAt = block.timestamp;

        emit ValidationResponded(validationId, ValidationStatus.Disputed);
    }

    /**
     * @dev Resuelve una disputa (solo admin)
     * @param declaredSkillId ID de la habilidad declarada
     * @param validationId ID de la validación
     * @param accepted Si la validación es aceptada o rechazada
     */
    function resolveDispute(uint256 declaredSkillId, uint256 validationId, bool accepted) external onlyRole(ADMIN_ROLE) {
        Validation storage validation = skillValidations[declaredSkillId][validationId];

        require(validation.status == ValidationStatus.Disputed, "Not disputed");

        validation.status = accepted ? ValidationStatus.Accepted : ValidationStatus.Rejected;
        validation.respondedAt = block.timestamp;

        if (accepted) {
            // Actualizar karma
            _updateKarma(declaredSkillId);
        }

        emit ValidationResponded(validationId, validation.status);
    }

    /**
     * @dev Actualiza el karma de una habilidad declarada
     * @param declaredSkillId ID de la habilidad declarada
     */
    function _updateKarma(uint256 declaredSkillId) internal {
        DeclaredSkill storage declaredSkill = declaredSkills[declaredSkillId];
        uint256 totalKarma = 0;
        uint256 validationCount = 0;

        for (uint256 i = 0; i < skillValidations[declaredSkillId].length; i++) {
            Validation storage validation = skillValidations[declaredSkillId][i];
            if (validation.status == ValidationStatus.Accepted) {
                // Fórmula simple: 10 puntos base + nivel validado * 5
                uint256 validationKarma = 10 + uint256(validation.validatedLevel) * 5;
                totalKarma += validationKarma;
                validationCount++;
            }
        }

        if (validationCount > 0) {
            declaredSkill.karma = totalKarma;
            skillKarma[declaredSkillId] = totalKarma;

            emit KarmaUpdated(declaredSkill.professional, declaredSkill.skillId, totalKarma);
        }
    }

    /**
     * @dev Obtiene el karma total de un profesional para una habilidad específica
     * @param professional Dirección del profesional
     * @param skillId ID de la habilidad
     */
    function getSkillKarma(address professional, uint256 skillId) external view returns (uint256) {
        uint256 totalKarma = 0;

        for (uint256 i = 0; i < professionalSkills[professional].length; i++) {
            uint256 declaredSkillId = professionalSkills[professional][i];
            DeclaredSkill storage declaredSkill = declaredSkills[declaredSkillId];

            if (declaredSkill.skillId == skillId) {
                totalKarma += declaredSkill.karma;
            }
        }

        return totalKarma;
    }

    /**
     * @dev Pausa el contrato (solo admin)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Reanuda el contrato (solo admin)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/core/TimeRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title TimeRegistry
 * @dev Implementa el sistema de registro horario laboral con validación bidireccional
 */
contract TimeRegistry is AccessControl, Pausable {
    using Counters for Counters.Counter;

    // Contadores
    Counters.Counter private _recordIdCounter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant KARMA_ROLE = keccak256("KARMA_ROLE");

    // Enums
    enum RecordStatus { Pending, Validated, Disputed, Rejected }

    // Estructuras
    struct TimeRecord {
        uint256 id;
        address employee;
        address company;
        uint256 startTime;
        uint256 endTime;
        string description;
        uint256[] skillIds;
        RecordStatus status;
        uint256 createdAt;
        uint256 validatedAt;
    }

    // Mappings
    mapping(uint256 => TimeRecord) public timeRecords;
    mapping(address => uint256[]) public employeeRecords;
    mapping(address => uint256[]) public companyRecords;

    // Eventos
    event TimeRecordCreated(uint256 indexed recordId, address indexed employee, address indexed company);
    event TimeRecordValidated(uint256 indexed recordId, address indexed validator);
    event TimeRecordDisputed(uint256 indexed recordId, address indexed disputer);
    event TimeRecordRejected(uint256 indexed recordId, address indexed rejector);

    /**
     * @dev Constructor
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(KARMA_ROLE, msg.sender);
    }

    /**
     * @dev Registra un nuevo registro horario
     * @param company Dirección de la empresa
     * @param startTime Timestamp de inicio
     * @param endTime Timestamp de fin
     * @param description Descripción de las actividades
     * @param skillIds IDs de las habilidades utilizadas
     */
    function registerTime(
        address company,
        uint256 startTime,
        uint256 endTime,
        string calldata description,
        uint256[] calldata skillIds
    ) external whenNotPaused {
        require(startTime < endTime, "Invalid time range");
        require(startTime > 0, "Invalid start time");

        uint256 recordId = _recordIdCounter.current();
        _recordIdCounter.increment();

        timeRecords[recordId] = TimeRecord({
            id: recordId,
            employee: msg.sender,
            company: company,
            startTime: startTime,
            endTime: endTime,
            description: description,
            skillIds: skillIds,
            status: RecordStatus.Pending,
            createdAt: block.timestamp,
            validatedAt: 0
        });

        employeeRecords[msg.sender].push(recordId);
        companyRecords[company].push(recordId);

        emit TimeRecordCreated(recordId, msg.sender, company);
    }

    /**
     * @dev Valida un registro horario (solo la empresa)
     * @param recordId ID del registro horario
     */
    function validateTimeRecord(uint256 recordId) external whenNotPaused {
        TimeRecord storage record = timeRecords[recordId];

        require(record.company == msg.sender, "Not authorized");
        require(record.status == RecordStatus.Pending, "Not pending");

        record.status = RecordStatus.Validated;
        record.validatedAt = block.timestamp;

        emit TimeRecordValidated(recordId, msg.sender);
    }

    /**
     * @dev Disputa un registro horario
     * @param recordId ID del registro horario
     */
    function disputeTimeRecord(uint256 recordId) external whenNotPaused {
        TimeRecord storage record = timeRecords[recordId];

        require(record.employee == msg.sender || record.company == msg.sender, "Not authorized");
        require(record.status == RecordStatus.Pending || record.status == RecordStatus.Validated, "Cannot dispute");

        record.status = RecordStatus.Disputed;

        emit TimeRecordDisputed(recordId, msg.sender);
    }

    /**
     * @dev Rechaza un registro horario
     * @param recordId ID del registro horario
     */
    function rejectTimeRecord(uint256 recordId) external whenNotPaused {
        TimeRecord storage record = timeRecords[recordId];

        require(record.company == msg.sender, "Not authorized");
        require(record.status == RecordStatus.Pending || record.status == RecordStatus.Disputed, "Cannot reject");

        record.status = RecordStatus.Rejected;

        emit TimeRecordRejected(recordId, msg.sender);
    }

    /**
     * @dev Resuelve una disputa (solo admin)
     * @param recordId ID del registro horario
     * @param validated Si el registro es validado o rechazado
     */
    function resolveDispute(uint256 recordId, bool validated) external onlyRole(ADMIN_ROLE) {
        TimeRecord storage record = timeRecords[recordId];

        require(record.status == RecordStatus.Disputed, "Not disputed");

        record.status = validated ? RecordStatus.Validated : RecordStatus.Rejected;

        if (validated) {
            record.validatedAt = block.timestamp;
            emit TimeRecordValidated(recordId, msg.sender);
        } else {
            emit TimeRecordRejected(recordId, msg.sender);
        }
    }

    /**
     * @dev Obtiene los registros horarios de un empleado
     * @param employee Dirección del empleado
     */
    function getEmployeeRecords(address employee) external view returns (uint256[] memory) {
        return employeeRecords[employee];
    }

    /**
     * @dev Obtiene los registros horarios de una empresa
     * @param company Dirección de la empresa
     */
    function getCompanyRecords(address company) external view returns (uint256[] memory) {
        return companyRecords[company];
    }

    /**
     * @dev Pausa el contrato (solo admin)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Reanuda el contrato (solo admin)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

